const items = $input.all();
const now = new Date().toISOString();
const services = [
  { name: 'Service 1', url: 'https://your-service-1.example.com/health' },
  { name: 'Service 2', url: 'https://your-service-2.example.com/health' },
  { name: 'Service 3', url: 'https://your-service-3.example.com/health' }
];

const results = items.map((item, idx) => {
  const service = services[idx] || { name: `Service ${idx + 1}`, url: 'unknown' };
  const statusCode = item.json?.statusCode || item.json?.$response?.statusCode || 0;
  const hasError = !!item.json?.error || statusCode >= 400 || statusCode === 0;
  return {
    name: service.name,
    url: service.url,
    statusCode: statusCode,
    isUp: !hasError && statusCode >= 200 && statusCode < 300,
    responseTime: item.json?.$response?.responseTime || 0,
    error: item.json?.error || ''
  };
});

const downServices = results.filter(r => !r.isUp);
const allUp = downServices.length === 0;

return [{
  json: {
    timestamp: now,
    totalServices: results.length,
    upCount: results.filter(r => r.isUp).length,
    downCount: downServices.length,
    allHealthy: allUp,
    hasDownService: !allUp,
    services: JSON.stringify(results),
    downServiceNames: downServices.map(s => s.name).join(', ') || 'None',
    summary: allUp ? 'All services healthy ✅' : `${downServices.length} service(s) down: ${downServices.map(s => s.name).join(', ')}`
  }
}];

